run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.20.0.0/24 --dest-ip-ranges=10.20.0.0/24 --layer4-configs=all '--description=inside Antwerp-DC range 1'
